const j = $input.first().json;
const key = (j.headers || {})['x-pipeline-key'];
if (!j.webhook_key || key !== j.webhook_key) return [{ json: { ok: false, error: 'bad webhook key' } }];
const b = j.body || {};
if (b.mode === 'url') return [{ json: { ok: true, mode: 'url', project_id: b.project_id, url: b.url } }];
const sources = Array.isArray(b.sources) ? b.sources : [];
if (!b.project_id || !sources.length) return [{ json: { ok: false, error: 'no sources' } }];
return sources.map(s => ({ json: { ok: true, mode: 'crawl', project_id: b.project_id, source_id: s.source_id, kind: s.kind, platform: s.platform, handle: s.handle } }));

// Один источник → один вызов Apify. Актор по площадке; хештеги — тот же instagram-scraper.
const s = $json;
let actor, input;
if (s.platform === 'tiktok') {
  actor = 'clockworks~tiktok-scraper';
  input = s.kind === 'hashtag' ? { hashtags: [s.handle], resultsPerPage: $('Настройки').first().json.results_limit }
                                : { profiles: [s.handle], resultsPerPage: $('Настройки').first().json.results_limit };
} else {
  actor = 'apify~instagram-scraper';
  input = s.kind === 'hashtag'
    ? { directUrls: [`https://www.instagram.com/explore/tags/${s.handle}/`], resultsType: 'posts', resultsLimit: $('Настройки').first().json.results_limit }
    : { directUrls: [`https://www.instagram.com/${s.handle}/`], resultsType: 'posts', resultsLimit: $('Настройки').first().json.results_limit, onlyPostsNewerThan: '7 days' };
}
return [{ json: { ...s, actor, input } }];

// Ответ Apify → items для radar/internal/ingest. Нормализация полей — на стороне MarkVision.
const src = $('→ запрос Apify').first().json;
const r = $input.first().json;
const body = Array.isArray(r.body) ? r.body : (r.body?.items || []);
const items = body.map(it => ({ ...it, platform: src.platform }));
const cost = Math.round(items.length / 1000 * $('Настройки').first().json.apify_cost_per_1000 * 10000) / 10000;
return [{ json: { project_id: src.project_id, source_id: src.source_id, provider: 'apify', platform: src.platform, cost_usd: cost, items,
  error: (r.statusCode >= 300 || !Array.isArray(body)) ? `Apify HTTP ${r.statusCode}` : null } }];

// Одна ссылка: ScrapeCreators отдаёт пост с метриками и video_url для Whisper.
const j = $json;
const u = j.url;
const platform = /tiktok\.com/.test(u) ? 'tiktok' : /youtu/.test(u) ? 'youtube' : /threads\./.test(u) ? 'threads' : /facebook|fb\.watch/.test(u) ? 'facebook' : 'instagram';
const endpoint = platform === 'tiktok' ? 'https://api.scrapecreators.com/v2/tiktok/video' : platform === 'youtube' ? 'https://api.scrapecreators.com/v1/youtube/video' : 'https://api.scrapecreators.com/v1/instagram/post';
return [{ json: { project_id: j.project_id, url: u, platform, endpoint } }];

const src = $('→ разбор ссылки').first().json;
const r = $input.first().json;
const b = (r.body && typeof r.body === 'object') ? r.body : {};
const post = b.data || b.post || b;
return [{ json: { project_id: src.project_id, source_id: null, provider: 'scrapecreators', platform: src.platform, cost_usd: 0.002,
  items: r.statusCode < 300 ? [{ ...post, url: src.url, platform: src.platform }] : [],
  error: r.statusCode >= 300 ? `ScrapeCreators HTTP ${r.statusCode}` : null } }];
